  // Observed deltas rounded up to 0.05 (ceilings 0.15 / 0.60); see SOURCES.md.
  "SOIC-8": { centerMm: 0.15, sizeMm: 0.55, largePadMm: 0.55 },
  "SOIC-14": { centerMm: 0.15, sizeMm: 0.55, largePadMm: 0.55 },
